// Naive B — the code comment's fix: per-face flip + push out of each brick,
// LearnOpenGL-style, still discrete (no sweep, per-brick resolution).
function closestPointOnBox(px, py, box) {
  const cx = Math.max(box.x, Math.min(px, box.x + box.w));
  const cy = Math.max(box.y, Math.min(py, box.y + box.h));
  return { x: cx, y: cy };
}

export function naiveB(state, dt) {
  const lost = step(state, dt);
  for (const brick of state.bricks) {
