// --- Brick collision (swept + discrete resolution) -------------------------

const EPS = 1e-9;

// Swept AABB: does the ball's box (half-extent r) moving from (px,py) by
// (dx,dy) touch the brick during the step? Returns { t, axis } or null.
// Degenerate axes (dx/dy === 0) leave the slab open: the entry time on that
// axis is -Infinity and never limits the result (see hamaluik: swept tests
// require the objects NOT to be already colliding — the caller falls back to
// the discrete resolver for the already-overlapping / dt === 0 case).
function sweptContact(px, py, dx, dy, r, brick) {
  let txEnter = -Infinity;
  let txExit = Infinity;
  let tyEnter = -Infinity;
  let tyExit = Infinity;

  if (dx !== 0) {
    const t1 = (brick.x - (px + r)) / dx;
    const t2 = (brick.x + brick.w - (px - r)) / dx;
    txEnter = Math.min(t1, t2);
    txExit = Math.max(t1, t2);
  } else if (px + r <= brick.x || px - r >= brick.x + brick.w) {
    return null; // moving parallel, never overlapping in x
  }

  if (dy !== 0) {
    const t1 = (brick.y - (py + r)) / dy;
    const t2 = (brick.y + brick.h - (py - r)) / dy;
    tyEnter = Math.min(t1, t2);
    tyExit = Math.max(t1, t2);
  } else if (py + r <= brick.y || py - r >= brick.y + brick.h) {
    return null;
  }

  const tEnter = Math.max(txEnter, tyEnter);
  const tExit = Math.min(txExit, tyExit);
  if (tEnter > tExit || tEnter > 1 || tExit < 0) return null;

  // The limiting axis is the one entered last along the path; equal entries
  // mean the corner was hit — both axes bounce (see to_fix.md D4b).
  if (txEnter === tyEnter) return { t: tEnter, axis: 'xy' };
  return txEnter > tyEnter ? { t: tEnter, axis: 'x' } : { t: tEnter, axis: 'y' };
}
```

