```js
// --- Brick collision resolution --------------------------------------------
//
// The ball is an AABB of half-extent BALL_R. Two passes run after the ball has
// moved in step():
//
//   1. Swept pass — the path [prev, current] is tested against every alive
//      brick (swept AABB). This is what catches tunneling (to_fix.md D2): a
//      step longer than the brick must not skip it. The earliest contact
//      decides the bounce; every brick touched up to that point is destroyed.
//      One bounce per pass.
//
//   2. Discrete pass — the fallback when the ball did not move this step
//      (dt = 0) or already overlaps a brick at the start of the step (the
//      swept test requires the bodies NOT to be already colliding — see
//      hamaluik, swept AABB). All overlapped bricks are destroyed, then the
//      bounce axis is chosen from the combined penetrations: a seam (two
//      bricks pushing in opposite directions on the same axis) wedges that
//      axis, and the other one is used (to_fix.md D3/D5). Equal penetrations
//      on both axes are a corner: both velocities flip (to_fix.md D4b).

const EPSILON = 1e-9;

// True if the ball box touches the brick along the segment from (px, py) by
// (dx, dy) within this step. Returns { t, axis } where t is the entry time in
// [0, 1] and axis is 'x', 'y' or 'xy' (corner), or null.
function sweptContact(px, py, dx, dy, r, brick) {
  let txEnter = -Infinity;
  let txExit = Infinity;
  if (dx !== 0) {
    txEnter = Math.min((brick.x - (px + r)) / dx, (brick.x + brick.w - (px - r)) / dx);
    txExit = Math.max((brick.x - (px + r)) / dx, (brick.x + brick.w - (px - r)) / dx);
  } else if (px + r <= brick.x || px - r >= brick.x + brick.w) {
    return null;
  }

  let tyEnter = -Infinity;
  let tyExit = Infinity;
  if (dy !== 0) {
    tyEnter = Math.min((brick.y - (py + r)) / dy, (brick.y + brick.h - (py - r)) / dy);
    tyExit = Math.max((brick.y - (py + r)) / dy, (brick.y + brick.h - (py - r)) / dy);
  } else if (py + r <= brick.y || py - r >= brick.y + brick.h) {
    return null;
  }

  const tEnter = Math.max(txEnter, tyEnter);
  const tExit = Math.min(txExit, tyExit);
  if (tEnter < 0 || tEnter > 1 || tEnter > tExit || tExit < 0) return null;

  if (Math.abs(txEnter - tyEnter) < EPSILON) return { t: tEnter, axis: 'xy' };
  return txEnter > tyEnter ? { t: tEnter, axis: 'x' } : { t: tEnter, axis: 'y' };
}

function breakBrick(state, brick) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
}

// Bounces the ball off every brick touched this step and destroys those
// bricks. Assumes the ball has already moved from (prevX, prevY).
function resolveBricks(state, prevX, prevY) {
  const { ball } = state;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  if (dx !== 0 || dy !== 0) {
    const hits = [];
    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      const hit = sweptContact(prevX, prevY, dx, dy, ball.r, brick);
      if (hit) hits.push({ brick, hit });
    }
    if (hits.length > 0) {
      hits.sort((a, b) => a.hit.t - b.hit.t);
      const first = hits[0];
      for (const { brick, hit } of hits) {
        if (hit.t <= first.hit.t + EPSILON) breakBrick(state, brick);
      }
      const { brick, hit } = first;
      const { t, axis } = hit;
      ball.x = prevX + dx * t;
      ball.y = prevY + dy * t;
      if (axis !== 'x') {
        ball.vy = dy >= 0 ? -Math.abs(ball.vy) : Math.abs(ball.vy);
        ball.y = dy >= 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
      }
      if (axis !== 'y') {
        ball.vx = dx >= 0 ? -Math.abs(ball.vx) : Math.abs(ball.vx);
        ball.x = dx >= 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
      }
      return;
    }
  }

  const overlapped = state.bricks.filter((b) => b.alive && collides(ball, b));
  if (overlapped.length === 0) return;
  for (const brick of overlapped) breakBrick(state, brick);

  // Combined penetrations: dir -1 pushes toward the negative side of the axis.
  const pushes = { x: { '-1': [], '1': [] }, y: { '-1': [], '1': [] } };
  for (const brick of overlapped) {
    const rightIn = ball.x + ball.r - brick.x;   // brick left face → push -x
    const leftIn = brick.x + brick.w - (ball.x - ball.r); // brick right face → push +x
    const bottomIn = ball.y + ball.r - brick.y;  // brick top face → push -y
    const topIn = brick.y + brick.h - (ball.y - ball.r); // brick bottom face → push +y
    if (rightIn < leftIn) pushes.x['-1'].push(rightIn);
    else if (leftIn < rightIn) pushes.x['1'].push(leftIn);
    if (bottomIn < topIn) pushes.y['-1'].push(bottomIn);
    else if (topIn < bottomIn) pushes.y['1'].push(topIn);
  }

  const options = [];
  for (const axis of ['x', 'y']) {
    const neg = pushes[axis]['-1'];
    const pos = pushes[axis]['1'];
    if (neg.length === 0 && pos.length === 0) continue;
    if (neg.length > 0 && pos.length > 0) continue; // wedged: a seam squeezes both ways
    const dir = neg.length > 0 ? -1 : 1;
    const depth = Math.max(...(neg.length > 0 ? neg : pos));
    options.push({ axis, dir, depth });
  }

  let chosen;
  if (options.length === 0) {
    // Fully wedged (pocket) or no definite face: follow the dominant motion.
    chosen =
      Math.abs(ball.vx) > Math.abs(ball.vy) && ball.vx !== 0
        ? { axis: 'x', dir: Math.sign(ball.vx) < 0 ? 1 : -1, depth: 0 }
        : { axis: 'y', dir: ball.vy < 0 ? 1 : -1, depth: 0 };
  } else if (options.length === 1) {
    chosen = options[0];
  } else if (Math.abs(options[0].depth - options[1].depth) < EPSILON) {
    // Corner: equal penetration on both axes → both bounce (to_fix.md D4b).
    const x = options.find((o) => o.axis === 'x');
    const y = options.find((o) => o.axis === 'y');
    ball.vx = x.dir < 0 ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    ball.vy = y.dir < 0 ? -Math.abs(ball.vy) : Math.abs(ball.vy);
