+// Swept AABB test: does the ball box (half-extent r), moving from (px, py) by
+// (dx, dy), touch the box during the step? Returns { t, axis } where t is the
+// entry time in [0, 1] and axis is 'x', 'y' or 'xy' (corner), or null.
+// An axis with zero motion leaves its slab open only if the boxes already
+// overlap on that axis; entry times before the step (already colliding) are
+// rejected — the caller falls back to the discrete pass for those (see
+// hamaluik: the swept test requires the bodies NOT to already collide).
+function sweptContact(px, py, dx, dy, r, box) {
+  let txEnter = -Infinity;
+  let txExit = Infinity;
+  if (dx !== 0) {
+    const t1 = (box.x - (px + r)) / dx;
+    const t2 = (box.x + box.w - (px - r)) / dx;
+    txEnter = Math.min(t1, t2);
+    txExit = Math.max(t1, t2);
+  } else if (px + r <= box.x || px - r >= box.x + box.w) {
+    return null;
+  }
