  let txE = -Infinity, txX = Infinity, tyE = -Infinity, tyX = Infinity;
  if (dx !== 0) { const a=(box.x-(px+r))/dx, b=(box.x+box.w-(px-r))/dx; txE=Math.min(a,b); txX=Math.max(a,b); }
  else if (px+r <= box.x || px-r >= box.x+box.w) return false;
  if (dy !== 0) { const a=(box.y-(py+r))/dy, b=(box.y+box.h-(py-r))/dy; tyE=Math.min(a,b); tyX=Math.max(a,b); }
  else if (py+r <= box.y || py-r >= box.y+box.h) return false;
  const tE = Math.max(txE, tyE), tX = Math.min(txX, tyX);
  return !(tE < 0 || tE > 1 || tE > tX || tX < 0);
}

const state = createState(8); // speed 890 → step 44.5px
let crosses = 0, frames = 0;
for (let i = 0; i < 120000 && state.level <= 10; i++) {
  const prevX = state.ball.x, prevY = state.ball.y;
