// neon.js — NÉON, a minimalist brick breaker (zero dependencies).
//
// Pure logic (grid, ball physics, brick collision, score) lives in this module
// and is imported by the tests (`node --test`) without a browser: the module
// runs nothing on import, only `boot()` touches the DOM.

import { palette, brickColor } from './theme.js';
import { createGlowMap, drawGlow, GLOW_W, GLOW_H } from './bloom.js';

// --- Axis convention -------------------------------------------------------

// Screen coordinates, as the canvas defines them: the origin is the TOP-LEFT
// corner and **Y GROWS DOWNWARD**. So `y = 0` is the ceiling, `y = HEIGHT` the
// line through which the ball is lost, and a ball climbing toward the bricks
// has a NEGATIVE `vy`. Every sign in this file follows from that single
// choice — the launch velocity, each bounce, and the paddle test `vy > 0`.
//
// The constants below name the sign a velocity component takes per heading.
// Assert against them rather than against a bare `-1` / `1`: a test reading
// `Math.sign(ball.vy) === UP` states its intent, where a hard-coded `-1` only
// states an arithmetic fact and quietly means the opposite if the convention
// ever flips.
//
//   UP    (-1)  toward the ceiling and the bricks
//   DOWN  (+1)  toward the paddle and the loss line
//   LEFT  (-1)  toward x = 0
//   RIGHT (+1)  toward x = WIDTH

export const UP = -1;
export const DOWN = 1;
export const LEFT = -1;
export const RIGHT = 1;

// --- Field constants -------------------------------------------------------

export const WIDTH = 640;
export const HEIGHT = 480;

export const PADDLE_W = 96;
export const PADDLE_H = 12;
export const PADDLE_Y = HEIGHT - 32;

export const BALL_R = 7;

export const BRICK_ROWS = 5;
export const BRICK_COLS = 8;
export const BRICK_W = 72;
export const BRICK_H = 20;
export const BRICK_GAP = 8;
export const BRICK_TOP = 48;

const STORAGE_KEY = 'neon.best';

// --- State construction ----------------------------------------------------

// Builds the brick grid for a given level.
// The higher the level, the more points bricks are worth.
export function makeBricks(level = 1) {
  const bricks = [];
  const offsetX = (WIDTH - (BRICK_COLS * (BRICK_W + BRICK_GAP) - BRICK_GAP)) / 2;
  for (let row = 0; row < BRICK_ROWS; row++) {
    for (let col = 0; col < BRICK_COLS; col++) {
      bricks.push({
        x: offsetX + col * (BRICK_W + BRICK_GAP),
        y: BRICK_TOP + row * (BRICK_H + BRICK_GAP),
        w: BRICK_W,
        h: BRICK_H,
        row,
        alive: true,
        points: (BRICK_ROWS - row) * 10 * level,
      });
    }
  }
  return bricks;
}

// Ball speed as a function of the level (ramps up with each level).
export function ballSpeed(level = 1) {
  return 260 + (level - 1) * 90;
}

// Creates a fresh game state.
export function createState(level = 1) {
  const speed = ballSpeed(level);
  return {
    level,
    lives: 3,
    score: 0,
    combo: 0,
    best: 0,
    running: false,
    paddle: { x: (WIDTH - PADDLE_W) / 2, y: PADDLE_Y, w: PADDLE_W, h: PADDLE_H },
    ball: { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: speed * 0.5, vy: -speed },
    bricks: makeBricks(level),
  };
}

// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Brick collision resolution --------------------------------------------
//
// The ball is an AABB of half-extent BALL_R. Bounces happen in two passes
// after the ball has moved in step():
//
//   1. Swept pass — the path [prev, current] is tested against every alive
//      brick (swept AABB). This is what catches tunneling (to_fix.md D2): a
//      step longer than a brick must not skip it. The earliest contact decides
//      the bounce; every brick touched up to that point is destroyed. One
//      bounce per pass.
//
//   2. Discrete pass — the fallback when the ball did not move this step
//      (dt = 0) or already overlaps a brick at the start of the step (the
//      swept test requires the bodies NOT to be already colliding — see
//      hamaluik, swept AABB). All overlapped bricks are destroyed, then the
//      bounce axis comes from the combined penetrations: a seam (two bricks
//      pushing in opposite directions on the same axis) wedges that axis and
//      the other one is used (to_fix.md D3/D5); equal penetrations on both
//      axes are a corner and both velocities flip (to_fix.md D4b).

const EPSILON = 1e-9;

// Swept AABB test: does the ball box (half-extent r), moving from (px, py) by
// (dx, dy), touch the box during the step? Returns { t, axis } where t is the
// entry time in [0, 1] and axis is 'x', 'y' or 'xy' (corner), or null.
// An axis with zero motion leaves its slab open only if the boxes already
// overlap on that axis; entry times before the step (already colliding) are
// rejected — the caller falls back to the discrete pass for those (see
// hamaluik: the swept test requires the bodies NOT to already collide).
function sweptContact(px, py, dx, dy, r, box) {
  let txEnter = -Infinity;
  let txExit = Infinity;
  if (dx !== 0) {
    const t1 = (box.x - (px + r)) / dx;
    const t2 = (box.x + box.w - (px - r)) / dx;
    txEnter = Math.min(t1, t2);
    txExit = Math.max(t1, t2);
  } else if (px + r <= box.x || px - r >= box.x + box.w) {
    return null;
  }

  let tyEnter = -Infinity;
  let tyExit = Infinity;
  if (dy !== 0) {
    const t1 = (box.y - (py + r)) / dy;
    const t2 = (box.y + box.h - (py - r)) / dy;
    tyEnter = Math.min(t1, t2);
    tyExit = Math.max(t1, t2);
  } else if (py + r <= box.y || py - r >= box.y + box.h) {
    return null;
  }

  const tEnter = Math.max(txEnter, tyEnter);
  const tExit = Math.min(txExit, tyExit);
  if (tEnter < 0 || tEnter > 1 || tEnter > tExit || tExit < 0) return null;

  // The limiting axis is the one entered last along the path; equal entries
  // mean the corner was hit and both axes bounce (to_fix.md D4b).
  if (Math.abs(txEnter - tyEnter) < EPSILON) return { t: tEnter, axis: 'xy' };
  return txEnter > tyEnter ? { t: tEnter, axis: 'x' } : { t: tEnter, axis: 'y' };
}

// Credits one destroyed brick exactly as frame() did before: combo first,
// then the score uses the incremented combo.
function breakBrick(state, brick) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
}

// Bounces the ball off every brick touched this step and destroys those
// bricks. Assumes the ball has already moved from (prevX, prevY).
function resolveBricks(state, prevX, prevY) {
  const { ball } = state;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  // Swept pass: the path, not the final position, decides (to_fix.md D2).
  if (dx !== 0 || dy !== 0) {
    const hits = [];
    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      const hit = sweptContact(prevX, prevY, dx, dy, ball.r, brick);
      if (hit) hits.push({ brick, hit });
    }
    if (hits.length > 0) {
      hits.sort((a, b) => a.hit.t - b.hit.t);
      const first = hits[0];
      for (const { brick, hit } of hits) {
        if (hit.t <= first.hit.t + EPSILON) breakBrick(state, brick);
      }
      const { brick, hit } = first;
      ball.x = prevX + dx * hit.t;
      ball.y = prevY + dy * hit.t;
      // One bounce per pass: flip only the axis of the entry face (both on a
      // corner), then push the ball out through that face.
      if (hit.axis !== 'x') {
        ball.vy = dy >= 0 ? -Math.abs(ball.vy) : Math.abs(ball.vy);
        ball.y = dy >= 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
      }
      if (hit.axis !== 'y') {
        ball.vx = dx >= 0 ? -Math.abs(ball.vx) : Math.abs(ball.vx);
        ball.x = dx >= 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
      }
      return;
    }
  }

  // Discrete pass: the ball did not move this step (dt = 0) or was already
  // overlapping at the start (swept tests reject those).
  const overlapped = state.bricks.filter((b) => b.alive && collides(ball, b));
  if (overlapped.length === 0) return;
  for (const brick of overlapped) breakBrick(state, brick);

  // Combined penetrations per axis: dir -1 pushes toward the negative side.
  const pushes = { x: { '-1': [], '1': [] }, y: { '-1': [], '1': [] } };
  for (const brick of overlapped) {
    const rightIn = ball.x + ball.r - brick.x;            // brick left face → -x
    const leftIn = brick.x + brick.w - (ball.x - ball.r); // brick right face → +x
    const bottomIn = ball.y + ball.r - brick.y;           // brick top face → -y
    const topIn = brick.y + brick.h - (ball.y - ball.r);  // brick bottom face → +y
    if (rightIn < leftIn) pushes.x['-1'].push(rightIn);
    else if (leftIn < rightIn) pushes.x['1'].push(leftIn);
    if (bottomIn < topIn) pushes.y['-1'].push(bottomIn);
    else if (topIn < bottomIn) pushes.y['1'].push(topIn);
  }

  const options = [];
  for (const axis of ['x', 'y']) {
    const neg = pushes[axis]['-1'];
    const pos = pushes[axis]['1'];
    if (neg.length === 0 && pos.length === 0) continue;
    if (neg.length > 0 && pos.length > 0) continue; // wedged: a seam squeezes both ways
    const dir = neg.length > 0 ? -1 : 1;
    options.push({ axis, dir, depth: Math.max(...(neg.length > 0 ? neg : pos)) });
  }

  if (options.length === 2 && Math.abs(options[0].depth - options[1].depth) < EPSILON) {
    // Corner: equal penetration on both axes → both bounce (to_fix.md D4b).
    const x = options[0].axis === 'x' ? options[0] : options[1];
    const y = options[0].axis === 'y' ? options[0] : options[1];
    ball.vx = x.dir < 0 ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    ball.vy = y.dir < 0 ? -Math.abs(ball.vy) : Math.abs(ball.vy);
    ball.x = x.dir < 0
      ? Math.min(...overlapped.map((b) => b.x)) - ball.r
      : Math.max(...overlapped.map((b) => b.x + b.w)) + ball.r;
    ball.y = y.dir < 0
      ? Math.min(...overlapped.map((b) => b.y)) - ball.r
      : Math.max(...overlapped.map((b) => b.y + b.h)) + ball.r;
    return;
  }

  // The clear axis with the smallest penetration is the face that was hit
  // (noonat: "the axis with the smallest overlap").
  let chosen = null;
  for (const opt of options) {
    if (!chosen || opt.depth < chosen.depth) chosen = opt;
  }
  if (!chosen) {
    // Fully wedged (pocket) or no definite face: follow the dominant motion.
    chosen =
      Math.abs(ball.vx) > Math.abs(ball.vy) && ball.vx !== 0
        ? { axis: 'x', dir: Math.sign(ball.vx) < 0 ? 1 : -1, depth: 0 }
        : { axis: 'y', dir: ball.vy < 0 ? 1 : -1, depth: 0 };
  }

  if (chosen.axis === 'x') {
    ball.vx = chosen.dir < 0 ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    ball.x = chosen.dir < 0
      ? Math.min(...overlapped.map((b) => b.x)) - ball.r
      : Math.max(...overlapped.map((b) => b.x + b.w)) + ball.r;
  } else {
    ball.vy = chosen.dir < 0 ? -Math.abs(ball.vy) : Math.abs(ball.vy);
    ball.y = chosen.dir < 0
      ? Math.min(...overlapped.map((b) => b.y)) - ball.r
      : Math.max(...overlapped.map((b) => b.y + b.h)) + ball.r;
  }
}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the bricks, the walls, the ceiling and the paddle. The brick bounce is a
// resolution over the ball's path, so no step — however long — can jump a
// brick (tunneling, see to_fix.md D2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const prevX = ball.x;
  const prevY = ball.y;
  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Bricks: swept path detection + one bounce per pass (see resolveBricks).
  resolveBricks(state, prevX, prevY);

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle — swept over the same step: the old position-in-band test let a
  // fast ball jump the whole 12 px band in one step (to_fix.md D6).
  if (ball.vy > 0) {
    const paddleBox = { x: paddle.x, y: paddle.y, w: paddle.w, h: paddle.h };
    const hit = sweptContact(prevX, prevY, ball.x - prevX, ball.y - prevY, ball.r, paddleBox);
    if (hit && hit.axis !== 'x') {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Rendering (DOM) -------------------------------------------------------

// Main render loop. Brick destruction, score and bounce now live in step()
// (see the brick collision section); this loop only draws what is still alive.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: draw the survivors.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
  ctx.fillStyle = '#39ff14';
  ctx.beginPath();
  ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
  ctx.fill();

  // HUD
  ctx.fillStyle = palette.text;
  ctx.font = '16px monospace';
  ctx.fillText(`Score ${state.score}`, 12, 24);
  ctx.fillText(`Best ${state.best}`, WIDTH - 110, 24);
  ctx.fillText(`Lives ${state.lives}`, WIDTH / 2 - 30, 24);
}

// --- Boot (browser entry point) --------------------------------------------

// Starts the game: wires up the canvas, the mouse and the animation loop.
// The only function that depends on the DOM; never called on import.
export function boot(doc = document) {
  const canvas = doc.getElementById('game');
  const ctx = canvas.getContext('2d');
  canvas.width = WIDTH;
  canvas.height = HEIGHT;

  const state = createState(1);
  state.best = loadBest(doc.defaultView?.localStorage ?? globalThis.localStorage);
  state.running = true;

  // Glow pass: a coarse offscreen light map, stretched over the field.
  const offscreen = doc.createElement('canvas');
  offscreen.width = GLOW_W;
  offscreen.height = GLOW_H;
  const glow = {
    map: createGlowMap(),
    image: offscreen.getContext('2d').createImageData(GLOW_W, GLOW_H),
  };

  // Move the paddle with the mouse.
  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left - state.paddle.w / 2;
    state.paddle.x = Math.max(0, Math.min(WIDTH - state.paddle.w, x));
  });

  let last = performance.now();
  function loop(now) {
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;

    if (state.running) {
      const lost = step(state, dt);
      if (lost) {
        state.lives -= 1;
        state.combo = 0;
        if (state.lives <= 0) {
          state.best = saveBest(globalThis.localStorage, state.score);
          Object.assign(state, createState(state.level));
          state.best = loadBest(globalThis.localStorage);
        } else {
          // relaunch the ball
          state.ball = createState(state.level).ball;
        }
      }

      // Level cleared: all bricks broken
      if (state.bricks.every((b) => !b.alive)) {
        state.level += 1;
        state.bricks = makeBricks(state.level);
        state.ball = createState(state.level).ball;
      }
    }

    frame(ctx, state);
    drawGlow(ctx, glow, state, WIDTH, HEIGHT, offscreen);
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  return state;
}

