content.text:
// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  ballSpeed,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  BALL_R,
  PADDLE_Y,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// Local helpers --------------------------------------------------------------

function row(state, r) {
  return state.bricks.filter((b) => b.row === r);
}

// Brick bounce — D1: a brick hit must bounce the ball AND push it out.
// (to_fix.md D1: the ball plowed straight through because frame() only
// destroyed the brick and never touched the ball's velocity.)
test('D1: top-face hit flips vy upward and leaves the ball outside the brick', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // col 0, row 0: x=4..76, y=48..68
  state.ball = { x: brick.x + brick.w / 2, y: 52, r: BALL_R, vx: 0, vy: ballSpeed(1) }; // coming DOWN, overlapping the top face
  step(state, 0);
  assert.ok(state.ball.vy < 0, `vy must flip upward (got ${state.ball.vy})`);
  assert.ok(state.ball.y + state.ball.r <= brick.y, `ball must be above the brick (got ${state.ball.y})`);
  assert.equal(brick.alive, false);
});

// Brick bounce — D4a: the axis of the bounce is the face that was hit.
test('D4a: a left-face hit flips vx, not vy', () => {
  const state = createState(1);
  const brick = row(state, 0)[4]; // col 4: x=324..396, y=48..68
  state.ball = { x: 325, y: 56, r: BALL_R, vx: 260, vy: 100 }; // enters from the left
  step(state, 0);
  assert.ok(state.ball.vx < 0, `vx must flip left (got ${state.ball.vx})`);
  assert.equal(state.ball.vy, 100, `vy must be untouched (got ${state.ball.vy})`);
});

// Brick bounce — D4b: equal penetration on both axes is a corner: both flip.
test('D4b: a corner hit with equal penetration flips both axes', () => {
  const state = createState(1);
  const brick = row(state, 0)[4]; // col 4: x=324..396, y=48..68
  state.ball = { x: 324, y: 48, r: BALL_R, vx: 260, vy: 260 }; // px == py == 7
  step(state, 0);
  assert.ok(state.ball.vx < 0, `vx must flip (got ${state.ball.vx})`);
  assert.ok(state.ball.vy < 0, `vy must flip (got ${state.ball.vy})`);
});

// Brick bounce — D2: a step longer than a brick must still bounce (swept
// detection). At L6 the 50 ms step (35.5 px) is longer than brick + ball
// (34 px): an overlap-only check at the final position misses the brick.
test('D2: no brick can be crossed without a bounce, even at max step (L6, dt=50ms)', () => {
  const state = createState(6); // speed 710 → step 35.5
  const brick = state.bricks[0]; // y=48..68
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(6) };
  step(state, 0.05); // lands at y=75.5: fully below the brick, no overlap
  assert.equal(brick.alive, false, 'the crossed brick must be destroyed');
  assert.ok(state.ball.vy < 0, `vy must flip upward (got ${state.ball.vy})`);
});

// Brick bounce — D3: two bricks straddled at a seam count as ONE bounce.
// The ball (diameter 14) is wider than the 8 px column gap, so it overlaps
// two bricks at once; a per-brick flip would invert vy twice and go through.
test('D3: a seam hit flips vy exactly once, not once per brick', () => {
  const state = createState(1);
  const [a, b] = row(state, 0); // a: x=4..76, b: x=84..156, gap 76..84
  state.ball = { x: 80, y: 52, r: BALL_R, vx: 0, vy: ballSpeed(1) }; // straddles the seam
  step(state, 0);
  assert.equal(a.alive, false);
  assert.equal(b.alive, false);
  assert.equal(state.ball.vy, -ballSpeed(1), `exactly one flip: vy must be -260 (got ${state.ball.vy})`);
});

// Brick bounce — D5: after the resolution the ball must be outside EVERY
// brick it touched, not just the first one resolved.
test('D5: after a seam hit the ball is outside every brick it touched', () => {
  const state = createState(1);
  const [a, b] = row(state, 0);
  state.ball = { x: 80, y: 52, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 0);
  assert.equal(collides(state.ball, a), false, 'ball still overlaps brick a');
  assert.equal(collides(state.ball, b), false, 'ball still overlaps brick b');
});

// Paddle — D6: a fast ball cannot jump the whole 12 px paddle band in one
// step. At L6, dt=0.03 (21.3 px) the old position-in-band test was skipped.
test('D6: a fast ball cannot pass through the paddle', () => {
  const state = createState(6); // speed 710
  state.paddle.x = (WIDTH - 96) / 2; // centered: 272..368
  state.ball = { x: 320, y: PADDLE_Y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(6) }; // bottom at 447
  step(state, 0.03); // lands at y=461.3 → bottom 468.3, beyond the band
  assert.ok(state.ball.vy < 0, `ball must bounce off the paddle (got ${state.ball.vy})`);
  assert.ok(state.ball.y + state.ball.r <= PADDLE_Y, `ball must be above the paddle (got ${state.ball.y})`);
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// TODO (#5): test comboMultiplier / scoreForBrick.
// TODO      : test level progression and loadBest/saveBest persistence.
